import heapq

def match(orders):
    trades = []
    book_buy = []  # heap of (-price, seq, id) for buy side (max price first)
    book_sell = []  # heap of (price, seq, id) for sell side (min price first)
    orders_info = {}  # id -> dict with side, price, qty, active
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = orders_info.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty
        info = {'side': side, 'price': price, 'qty': remaining, 'active': True}
        orders_info[oid] = info

        if side == 'buy':
            opp_heap = book_sell
        else:
            opp_heap = book_buy

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            top_id = top[2]
            top_info = orders_info.get(top_id)
            if not top_info or not top_info['active'] or top_info['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            top_price = top_info['price']

            if side == 'buy':
                if typ != 'market' and price < top_price:
                    break
            else:
                if typ != 'market' and price > top_price:
                    break

            trade_qty = min(remaining, top_info['qty'])
            trade_price = top_price

            if side == 'buy':
                trades.append([oid, top_id, trade_price, trade_qty])
            else:
                trades.append([top_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            top_info['qty'] -= trade_qty
            info['qty'] = remaining

            if top_info['qty'] == 0:
                top_info['active'] = False
                heapq.heappop(opp_heap)

        info['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            seq_counter += 1
            if side == 'buy':
                heapq.heappush(book_buy, (-price, seq_counter, oid))
            else:
                heapq.heappush(book_sell, (price, seq_counter, oid))
            info['active'] = True
        else:
            info['active'] = False

    return trades

